import Foundation

func allSubstrings(_ inputString: String) -> [String] {
    let length = inputString.count
    var result: [String] = []

    for i in 0..<length {
        for j in i + 1..<length + 1 {
            result.append(String(inputString[inputString.index(inputString.startIndex, offsetBy: i)..<inputString.index(inputString.startIndex, offsetBy: j)]))
        }
    }

    return result
}

func longestSubstring(_ strings: [String], k: Int) -> String? {
    if strings.count == 0 {
        return nil
    }

    var longestStr = ""

    for string in strings {
        let substrings = allSubstrings(string)
        for substr in substrings {
            let count = substrings.filter { $0.contains(substr) }.count
            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }

    return longestStr.count > 0 ? longestStr : nil
}
