function sortBooks(books) {
  return books.sort((a, b) => {
    // Case-sensitive comparison
    const titleA = a.toLowerCase();
    const titleB = b.toLowerCase();

    // Sort numbers before letters
    if (titleA[0] >= '0' && titleA[0] <= '9' && (titleB[0] < '0' || titleB[0] > '9')) {
      return -1;
    } else if (titleB[0] >= '0' && titleB[0] <= '9' && (titleA[0] < '0' || titleA[0] > '9')) {
      return 1;
    }

    // Sort based on starting letter, length, and ASCII values
    if (titleA[0] === titleB[0]) {
      const lengthA = titleA.length;
      const lengthB = titleB.length;

      // Sort based on length (descending order)
      if (lengthA === lengthB) {
        const asciiA = Array.from(titleA).reduce((acc, char) => acc + char.charCodeAt(0), 0);
        const asciiB = Array.from(titleB).reduce((acc, char) => acc + char.charCodeAt(0), 0);

        // Sort based on ASCII values (descending order)
        return asciiB - asciiA;
      }

      // Sort based on length (descending order)
      return lengthB - lengthA;
    }

    // Sort based on starting letter (ascending order)
    return titleA > titleB ? 1 : -1;
  });
}

